(()=>{
 const SM=StudyModel,SD=StudyData,D=RoadmapData,key='statics-study-coach-v1',esc=M.esc,read=k=>{try{const v=JSON.parse(localStorage.getItem(k)||'{}');return v&&typeof v==='object'&&!Array.isArray(v)?v:{};}catch{return {};}},state=SM.initialize(read(key),read('statics-mastery-v1'),D.problems),now=()=>Date.now();
 const concepts=AssessmentData.bank.map(q=>({...q,id:'concept-'+q.id,kind:'concept',topic:q.topic==='geometry'?'position':q.topic})),diagrams=SD.diagrams.map(q=>({...q,prompt:'Read coordinates of A and B from the dimensioned graph, then find rAB = B − A.',answer:[...q.A,...q.B,...q.answer]})),questions=[...SD.questions,...concepts,...diagrams,...SD.entries],byId=id=>questions.find(q=>q.id===id),save=()=>{try{localStorage.setItem(key,JSON.stringify(state));}catch{const el=$('coachStorage');if(el)el.textContent='Browser storage is full or unavailable. Export your progress before closing.';}};
 let session=null,pendingImport=null;const panel=(title,body)=>'<article class="panel"><h2>'+title+'</h2>'+body+'</article>',button=(id,text)=>`<button id="${id}">${text}</button>`,getQueue=()=>SM.queue(D.problems,state,read('statics-roadmap-v1'),now());
 for(const id of ['studyHub','coachPractice','coachSheet','coachTransfer']){const el=document.createElement('section');el.id=id;el.className='view';el.hidden=true;document.querySelector('main').appendChild(el);}
 const folder=document.createElement('details');folder.className='nav-folder';folder.id='coachFolder';folder.open=true;folder.innerHTML='<summary>Study tools</summary><div class="nav-children">'+[['home','Study today'],['method','Choose a method'],['error','Find the mistake'],['diagram','Read a diagram'],['calculator','TI-84 rehearsal'],['mixed','Mixed practice'],['sheet','Build equation sheet'],['transfer','Move progress between devices']].map(([kind,label])=>`<button data-coach-open="${kind}">${label}</button>`).join('')+'</div>';document.querySelector('nav').prepend(folder);
 function open(kind){if(window.examInProgress)return;if(kind==='home'){showView('studyHub');dashboard();}else if(kind==='sheet'){showView('coachSheet');sheet();}else if(kind==='transfer'){showView('coachTransfer');transfer();}else{start(kind);}folder.open=true;}
 document.querySelectorAll('[data-coach-open]').forEach(b=>b.onclick=()=>open(b.dataset.coachOpen));
 function dimensions(){const evidence=read('statics-mastery-v1'),scores=Curriculum.topics.map(t=>SM.metrics(t.id,D.problems,questions,state,evidence,now())),overall='<div class="coach-dimensions"><h3>Overall · current app content</h3>'+['understanding','application','retention'].map(name=>{const value=Math.round(scores.reduce((sum,m)=>sum+m[name],0)/scores.length);return '<label>'+name[0].toUpperCase()+name.slice(1)+' · '+value+'%<progress max="100" value="'+value+'" aria-label="Overall '+name+'"></progress></label>';}).join('')+'</div>';return overall+ '<p>These indicators describe performance in the current app, not a guarantee of exam readiness. <strong>Understanding:</strong> distinct concept, method, diagram, and calculator checks. <strong>Application:</strong> complete independent walkthroughs. <strong>Retention:</strong> another independent success in the same family at least seven days later. Repeating an answer immediately after feedback does not create understanding credit.</p>'+Curriculum.topics.map(topic=>{const m=SM.metrics(topic.id,D.problems,questions,state,evidence,now());return `<div class="coach-dimensions"><h3>${esc(topic.title)}</h3>${['understanding','application','retention'].map(name=>`<label>${name[0].toUpperCase()+name.slice(1)} · ${m[name]}%<progress max="100" value="${m[name]}" aria-label="${esc(topic.title)} ${name}"></progress></label>`).join('')}<p>${m.questions} short checks · ${m.families} calculation families · ${m.due} reviews due</p></div>`;}).join('');}
 function dashboard(){const queue=getQueue(),missed=questions.filter(q=>{const seen=state.questions[q.id];return seen&&(seen.correct===false||!seen.understoodAt&&now()-seen.lastAt>=SM.DAY);}),practised=Object.values(state.families).filter(f=>f.lastPractised).length;$('studyHub').innerHTML=panel('Your next study session',`<p id="coachStorage">Progress saves in this browser. Use the transfer tool to carry it to another device.</p><p><strong>${missed.length}</strong> short checks to revisit · <strong>${queue.filter(q=>q.priority<3).length}</strong> calculation families needing review · <strong>${practised}</strong> families practised</p><div class="actions">${button('coachReview','Start five-question review')}${button('coachMixed','Try mixed calculations')}${button('coachAllConcepts','Review fundamental concepts')}</div>`)+panel('Calculation review queue','<p>Prioritizes recent difficulties, due reviews, assisted work, and unpractised topics. Completing a full independent attempt updates its schedule.</p><div class="coach-queue">'+queue.slice(0,8).map(q=>`<button data-coach-problem="${q.id}"><strong>${esc(q.title)}</strong><span>${q.reason}</span></button>`).join('')+'</div>')+panel('Understanding · application · retention',dimensions());$('coachReview').onclick=()=>{const ids=[...missed.map(q=>q.id),...queue.map(q=>'method-'+q.topic)];const unique=[...new Set(ids)].filter(id=>byId(id)).slice(0,5);start('review',unique);};$('coachMixed').onclick=()=>start('mixed');$('coachAllConcepts').onclick=()=>start('concept');bindProblems($('studyHub'));}
 function shuffled(list){return [...list].map(item=>({item,r:Math.random()})).sort((a,b)=>a.r-b.r).map(x=>x.item);}
 function start(kind,ids){if(window.examInProgress)return;const pool=kind==='mixed'?shuffled(D.problems).slice(0,5).map(p=>'mixed:'+p.id):ids||shuffled(questions.filter(q=>kind==='calculator'?['calculator','entry'].includes(q.kind):q.kind===kind)).map(q=>q.id);session={kind,cards:pool,index:0,correct:0,checked:false,methodPassed:false,started:now()};showView('coachPractice');practice();}
 function practice(){if(!session)return;if(session.index>=session.cards.length){state.sessions.push({kind:session.kind,at:now(),correct:session.correct,total:session.cards.length});state.sessions=state.sessions.slice(-200);save();$('coachPractice').innerHTML=panel('Session complete',`<p>${session.correct} of ${session.cards.length} final checks correct.</p>${button('coachSessionHome','Return to Study today')}`);$('coachSessionHome').onclick=()=>open('home');return;}const id=session.cards[session.index],mixed=id.startsWith('mixed:'),p=mixed?D.problems.find(p=>p.id===id.slice(6)):null,q=mixed?{id,topic:p.group,kind:'mixed',prompt:p.prompt,options:Object.values(SD.methods),answer:Object.keys(SD.methods).indexOf(p.group)}:byId(id),number=session.index+1;
  $('coachPractice').innerHTML=panel(`${session.kind==='mixed'?'Unlabelled problem':'Practice'} · ${number} / ${session.cards.length}`,`<p>${q.prompt}</p>${q.kind==='diagram'?'<svg id="coachDiagram" viewBox="0 0 600 400" role="img" aria-label="Dimensioned coordinate diagram with A and B"></svg>':''}${q.kind==='entry'?'<label>Angle mode<select id="coachEntryMode"><option value="DEG">DEGREE</option><option value="RAD">RADIAN</option></select></label><label>Calculator expression<input id="coachEntry" type="text" autocomplete="off" spellcheck="false" maxlength="500" placeholder="Use *, /, ^ and parentheses"></label>':q.kind==='diagram'?'<div class="position-answer-grid">'+['Ax','Ay','Az','Bx','By','Bz','rABx','rABy','rABz'].map((label,i)=>`<label>${label} (m)<input data-coach-coordinate="${i}" type="number" step="any"></label>`).join('')+'</div>':'<fieldset class="answer-options"><legend>'+(mixed?'Choose your method first':'Choose an answer')+'</legend>'+q.options.map((option,i)=>`<label class="answer-option"><input type="radio" name="coachChoice" value="${i}"><span>${option}</span></label>`).join('')+'</fieldset>'}<div class="actions">${button('coachCheck','Check answer')}${button('coachNext','Next →')}${button('coachHome','Study today')}</div><div id="coachFeedback" role="status"></div><div id="coachMixedResult"></div>`);$('coachNext').disabled=true;$('coachHome').onclick=()=>open('home');$('coachNext').onclick=()=>{session.index++;session.checked=false;session.methodPassed=false;practice();};
  if(q.kind==='diagram')drawDiagram(q);
  $('coachCheck').onclick=()=>{if(session.checked)return;let answer,pass,explanation=q.explanation||'';if(q.kind==='entry'){if(!$('coachEntry').value.trim()){$('coachFeedback').textContent='Enter a calculator expression first.';return;}const result=SM.entryResult(q,$('coachEntry').value,$('coachEntryMode').value,M);pass=result.correct;answer=pass;explanation=pass?'The calculator expression and mode are appropriate.':'Try '+q.example+'. '+result.message;}else if(q.kind==='diagram'){const values=[...document.querySelectorAll('[data-coach-coordinate]')].map(el=>el.value.trim()===''?NaN:Number(el.value));if(values.some(v=>!Number.isFinite(v))){$('coachFeedback').textContent='Enter every coordinate and displacement component, including zeros.';return;}answer=values;pass=values.length===q.answer.length&&values.every((v,i)=>Number.isFinite(v)&&Math.abs(v-q.answer[i])<.01);explanation='Coordinates locate points. Displacement is end minus start: rAB = ('+q.answer.slice(6).join(', ')+') m.';}else{const selected=document.querySelector('input[name="coachChoice"]:checked');if(!selected){$('coachFeedback').textContent='Choose an answer first.';return;}answer=Number(selected.value);pass=answer===q.answer;}
   if(mixed){if(!pass){$('coachFeedback').innerHTML='<div class="assessment-feedback incorrect">Reconsider the requested quantity. The method to review is <strong>'+esc(SD.methods[p.group])+'</strong>.</div>';SM.recordCheck(state,p,false,now());save();return;}session.methodPassed=true;$('coachFeedback').textContent='Method selected. Now calculate the requested final check on paper or your TI-84.';$('coachCheck').disabled=true;mixedResult(p);return;}
   SM.recordQuestion(state,q.kind==='entry'?{...q,answer:true}:q,answer,now());save();session.checked=true;if(pass)session.correct++;$('coachFeedback').innerHTML='<div class="assessment-feedback '+(pass?'correct':'incorrect')+'"><strong>'+(pass?'Correct.':'Review this idea.')+'</strong><p>'+explanation+'</p></div>';$('coachCheck').disabled=true;$('coachNext').disabled=false;
  };
 }
 function mixedResult(p){const s=p.steps.filter(s=>s.fields).at(-1);$('coachMixedResult').innerHTML='<h3>Final-answer check</h3><p>Check these quantities after solving the problem. The topic title and walkthrough steps stay hidden until you open the explanation.</p><div class="position-answer-grid">'+s.fields.map((f,i)=>`<label>${esc(f.label)}<input data-mixed-field="${i}" type="number" step="any"></label>`).join('')+'</div>'+button('coachMixedCheck','Check final result')+button('coachMixedWalk','Open full walkthrough')+'<div id="coachMixedFeedback" role="status"></div>';$('coachMixedWalk').onclick=()=>problem(p.id);$('coachMixedCheck').onclick=()=>{if(session.checked)return;const answers=Object.fromEntries([...document.querySelectorAll('[data-mixed-field]')].map(el=>[el.dataset.mixedField,el.value])),pass=D.correct(s,answers,3);SM.recordCheck(state,p,pass,now());save();if(pass){session.correct++;session.checked=true;$('coachNext').disabled=false;$('coachMixedCheck').disabled=true;$('coachMixedFeedback').textContent='Final result correct. Full walkthrough completion is tracked separately.';}else $('coachMixedFeedback').textContent=SM.diagnose(p,s,answers,TIRecipes);};}
 function drawDiagram(q){const z=[0,0,0],items=[];for(const [name,point] of [['A',q.A],['B',q.B]]){const x=[point[0],0,0],xy=[point[0],point[1],0];for(const [a,b,label] of [[z,x,'x = '+point[0]+' m'],[x,xy,'y = '+point[1]+' m'],[xy,point,'z = '+point[2]+' m']])items.push({start:a,end:b,label:label+' · '+name,color:name==='A'?'#8cbcff':'#efbd77',dashed:true,arrow:false});items.push({start:z,end:point,label:name,color:name==='A'?'#8cbcff':'#efbd77',arrow:false,pointEnd:name});}window.GraphScales?.refit('coachDiagram');Engineering.diagram('coachDiagram',q.A[2]||q.B[2]?'iso':'xy',items,[],'m');}
 function problem(id){if(window.examInProgress)return;const p=D.problems.find(p=>p.id===id);if(!p)return;GuidedRoadmap.open(p.group);GuidedRoadmap.selectProblem(id);}
 function bindProblems(scope){scope.querySelectorAll('[data-coach-problem]').forEach(b=>b.onclick=()=>problem(b.dataset.coachProblem));}
 function sheetFormula(e){const t=s=>'<mtext>'+esc(s)+'</mtext>',f=(a,b)=>'<mfrac>'+t(a)+t(b)+'</mfrac>',m=body=>'<math display="block"><mrow>'+body+'</mrow></math>',special={vector:m(t('rAB = B − A'))+m(t('uAB = ')+f('rAB','|rAB|'))+m(t('F = |F|uAB')),direction:m(t('θ = tan⁻¹(')+f('Ry','Rx')+t(')'))+m(t('with quadrant correction')),angle:m(t('cos θ = ')+f('A·B','|A||B|')),load:m(t('FR = ∫w dx; Q = ∫xw dx'))+m(t('x̄ = ')+f('Q','FR')),power:m(t('∫c xⁿ dx = c')+'<mfrac><msup><mi>x</mi><mrow><mi>n</mi><mo>+</mo><mn>1</mn></mrow></msup><mrow><mi>n</mi><mo>+</mo><mn>1</mn></mrow></mfrac>'+t(' + C')),shapes:m(t('Uniform: FR=wL; x̄=')+f('L','2'))+m(t('Triangle: FR=')+f('wmax L','2'))};return special[e.id]||e.formula.split(';').map(text=>m(t(text.trim()))).join('');}
 function sheet(){const selected=Array.isArray(state.sheet.selected)?state.sheet.selected:SD.equations.map(e=>e.id),size=Math.max(9,Math.min(13,Number(state.sheet.size)||10)),conditions=state.sheet.conditions!==false;$('coachSheet').innerHTML=panel('Build your letter-sized equation sheet','<p>Choose equations and conditions, then check the print preview. Print on letter paper in portrait orientation at 100% scale; disable browser headers and footers. The preview warns if your selected content exceeds the page.</p><div class="actions"><label>Font size<select id="coachSheetSize">'+[9,10,11,12,13].map(n=>`<option ${n===size?'selected':''}>${n}</option>`).join('')+'</select></label><label><input id="coachSheetConditions" type="checkbox" '+(conditions?'checked':'')+'> Include conditions and variable reminders</label>'+button('coachPrintSheet','Print equation sheet')+'</div><div class="coach-equation-choices">'+SD.equations.map(e=>`<label><input data-sheet-equation="${e.id}" type="checkbox" ${selected.includes(e.id)?'checked':''}>${e.title}</label>`).join('')+'</div><p id="coachSheetWarning" role="status"></p>')+'<div class="coach-paper-scroll"><div id="coachPaper" class="coach-paper" style="font-size:'+size+'pt"><h2>Solid Mechanics · equations</h2><div class="coach-paper-columns">'+SD.equations.filter(e=>selected.includes(e.id)).map(e=>'<section><strong>'+e.title+'</strong>'+sheetFormula(e)+(conditions?'<small>'+e.conditions+'</small>':'')+'</section>').join('')+'</div></div></div>';
  const update=()=>{state.sheet={selected:[...document.querySelectorAll('[data-sheet-equation]:checked')].map(el=>el.dataset.sheetEquation),size:Number($('coachSheetSize').value),conditions:$('coachSheetConditions').checked};save();sheet();};document.querySelectorAll('[data-sheet-equation]').forEach(el=>el.onchange=update);$('coachSheetSize').onchange=update;$('coachSheetConditions').onchange=update;const paper=$('coachPaper');const fits=()=>{const overflow=paper.scrollHeight>paper.clientHeight+2||paper.scrollWidth>paper.clientWidth+2;$('coachSheetWarning').textContent=overflow?'This selection exceeds one page. Reduce font size, hide conditions, or deselect equations before printing.':'Letter-size preview: check the browser print preview before using your sheet.';return !overflow;};requestAnimationFrame(fits);$('coachPrintSheet').onclick=()=>{if(!fits())return;document.body.classList.add('coach-print');window.print();};}
 window.addEventListener('afterprint',()=>document.body.classList.remove('coach-print'));
 function transfer(){pendingImport=null;$('coachTransfer').innerHTML=panel('Move progress between browsers','<p>Export a local JSON backup on this device. Open the same site on your laptop and import that file there. This transfers study records and notes; it does not create automatic syncing.</p>'+button('coachExport','Download progress backup')+'<label>Choose a progress backup<input id="coachImportFile" type="file" accept="application/json,.json"></label><div id="coachImportPreview" role="status"></div>'+button('coachApplyImport','Apply this backup and reload'));$('coachApplyImport').disabled=true;$('coachExport').onclick=()=>{const records={};for(const k of SM.keys){const value=localStorage.getItem(k);if(value!==null)records[k]=value;}const blob=new Blob([JSON.stringify({format:'statics-study-backup',version:1,exportedAt:new Date().toISOString(),records},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='statics-study-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('coachImportFile').onchange=async()=>{pendingImport=null;$('coachApplyImport').disabled=true;try{const file=$('coachImportFile').files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('Choose a backup smaller than 2 MB.');const text=await file.text();pendingImport=SM.validateBackup(JSON.parse(text));$('coachImportPreview').textContent='Ready to import '+Object.keys(pendingImport).length+' study record groups. Applying replaces the matching records in this browser; other data remains. Export your current progress first if you want to keep a separate copy.';$('coachApplyImport').disabled=false;}catch(error){$('coachImportPreview').textContent=error.message;}};$('coachApplyImport').onclick=()=>{if(!pendingImport||window.examInProgress)return;const before={};try{for(const k of Object.keys(pendingImport))before[k]=localStorage.getItem(k);for(const [k,value] of Object.entries(pendingImport))localStorage.setItem(k,value);window.location.reload();}catch(error){for(const [k,value] of Object.entries(before))try{value===null?localStorage.removeItem(k):localStorage.setItem(k,value);}catch{}$('coachImportPreview').textContent='Import did not complete. Existing records were restored where storage allowed. '+error.message;}};}
 function decorate(p,attempt){const layout=document.querySelector('#roadmap .roadmap-topic');if(!layout)return;layout.querySelector('.coach-notebook')?.remove();layout.classList.add('coach-roadmap-layout');const notebook=document.createElement('aside');notebook.className='coach-notebook panel';notebook.innerHTML='<h2>Problem notebook</h2><details open><summary>Givens and goal</summary><p>'+p.prompt+'</p>'+(p.graph?'<a href="#roadmapDiagram-'+p.id+'">Return to the diagram ↑</a>':'')+'</details><details open><summary>Your checked values</summary>'+p.steps.map((s,i)=>{if(!attempt.checked[i]||!D.correct(s,attempt.answers[i]||{},attempt.rounding[i]??attempt.sigFigs))return '';return '<p><strong>'+esc(s.title)+'</strong><br>'+(s.fields?s.fields.map((f,j)=>esc(f.label)+' = '+esc(attempt.answers[i][j])).join('<br>'):esc(s.options[Number(attempt.answers[i].choice)]))+'</p>';}).join('')+'</details><label>Your notes<textarea id="coachProblemNotes" rows="6" maxlength="10000"></textarea></label><p class="projection-note">Saved for this example in this browser.</p>';layout.appendChild(notebook);$('coachProblemNotes').value=String(state.notes[p.id]?.text||'').slice(0,10000);$('coachProblemNotes').oninput=()=>{state.notes[p.id]={text:$('coachProblemNotes').value,updatedAt:now()};save();};}
 function hintHTML(p,s,attempt,level){attempt.coachHints??={};attempt.coachHints[attempt.index]=level;return '<strong>Hint '+level+' of 3</strong><p>'+esc(level===1?s.hint.inputs:level===2?s.hint.reminder:s.why)+'</p>'+(level===3&&s.ti84?'<p>Calculator setup, without the final values:</p>'+s.ti84.rows.map(r=>'<code class="ti84-entry-example">'+esc(TI84.display(r.expression))+' → '+r.store+'</code>').join(''):'')+(level<3?button('coachMoreHint','More specific hint'):'<p>Open the worked explanation if you need the full derivation.</p>');}
 function bindHint(p,s,attempt,persist){const b=$('coachMoreHint');if(b)b.onclick=()=>{const level=Math.min(3,(attempt.coachHints?.[attempt.index]||1)+1);$('roadmapHint').innerHTML=hintHTML(p,s,attempt,level);attempt.assisted=true;persist();bindHint(p,s,attempt,persist);};}
 function onCheck(p,s,answers,pass,attempt){const supplied=s.fields?s.fields.every((_,i)=>String(answers[i]??'').trim()!==''&&Number.isFinite(Number(answers[i]))):answers.choice!==undefined;if(!supplied)return 'Enter every requested value or choose an answer first.';if(!pass)attempt.assisted=true;attempt.coachAttempt??=String(now())+'-'+Math.random().toString(36).slice(2);SM.recordCheck(state,p,pass,now());save();return pass?'':SM.diagnose(p,s,answers,TIRecipes);}
 function onComplete(p,attempt){if(!attempt.coachAttempt)return;const independent=MasteryMath.independent(p,attempt,D.correct);SM.complete(state,p,attempt.coachAttempt||'legacy-'+p.id,independent,now());save();}
 function addDimensions(){const old=$('coachMasteryDimensions');if(old)old.remove();const el=document.createElement('article');el.id='coachMasteryDimensions';el.className='panel';el.innerHTML='<h2>Three dimensions of progress</h2>'+dimensions();$('mastery').appendChild(el);}
 window.StudyCoach={open,decorate,hintHTML,bindHint,onCheck,onComplete,state};const activate=StudyExperience.activate;StudyExperience.activate=name=>{activate(name);const titles={studyHub:['Study today','Choose a short review or return to a calculation you need to practise.'],coachPractice:['Practise choosing and applying methods','Work without a topic-title clue, then review the reasoning.'],coachSheet:['Build your equation sheet','Select equations and conditions for a letter-sized reference page.'],coachTransfer:['Take your progress with you','Export and import local study records between your devices.']};if(titles[name]){$('pageTitle').textContent=titles[name][0];$('pageDescription').textContent=titles[name][1];$('pageCategory').textContent='STUDY TOOLS';document.title=titles[name][0]+' | Statics Study Lab';}if(name==='mastery')addDimensions();};
 const notice=$('updateSplash');notice.querySelector('p').textContent='Study tools are ready: review queue, method decisions, find-the-mistake exercises, diagram and TI-84 practice, mixed problems, a persistent notebook, progressive hints, three progress indicators, equation-sheet builder, and progress transfer.';save();dashboard();if(!window.examInProgress)open('home');
})();
